// Instantly, Smartlead and a plain forwarder all name these fields differently.
// Normalise once here so nothing downstream has to know which tool sent the reply.
return $input.all().map((item) => {
  const b = item.json.body || item.json;

  const email = String(
    b.lead_email || b.from_email || b.email || (b.lead && b.lead.email) || ''
  ).toLowerCase().trim();

  const text = String(
    b.reply_text || b.reply_text_snippet || b.message || b.body_plain || b.text || ''
  ).trim();

  let domain = email.split('@')[1] || '';

  return { json: {
    lead_id: b.lead_id || (b.custom_variables && b.custom_variables.lead_id) || email,
    email: email,
    domain: domain,
    first_name: b.first_name || b.firstName || (b.lead && b.lead.first_name) || '',
    last_name: b.last_name || b.lastName || (b.lead && b.lead.last_name) || '',
    company: b.company_name || b.company || '',
    campaign: b.campaign_name || b.campaign_id || b.campaign || '',
    reply_text: text,
    received_at: new Date().toISOString()
  }};
});

// Unparseable classification defaults to 'unclear', which routes to a human.
// Silence is the one outcome a reply must never get.
const leads = $('normalise reply').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const lead = Object.assign({}, leads[i].json);
  const res = $input.all()[i].json || {};
  const text = String(((((res.choices || [])[0]) || {}).message || {}).content || '').trim();

  let data = { intent: 'unclear', confidence: 0, summary: 'Classifier returned nothing usable.', asked_a_question: false, referred_to_someone: '', follow_up_on: '', suggested_reply: '' };
  if (text) {
    // Some gateway models wrap JSON in a fence even when a schema is set.
    const body = text.startsWith('```') ? text.replace(/^```[a-z]*\n?/, '').replace(/```$/, '').trim() : text;
    try { data = JSON.parse(body); } catch (e) { /* keep the unclear default */ }
  }

  const optOut = ['unsubscribe', 'not_interested'].indexOf(data.intent) !== -1;
  const hot = data.intent === 'interested';

  out.push({ json: Object.assign({}, lead, data, {
    opt_out: optOut,
    hot: hot,
    stage: optOut ? 'suppressed' : (hot ? 'replied' : 'replied')
  })});
}

return out;

// Every reply produces exactly one alert. The suggested reply is included so the
// client can answer from their phone without opening the CRM.
const source = $('read classification').first().json;
const intent = source.intent;

const icon = { interested: ':fire:', not_now: ':hourglass:', not_interested: ':no_entry:', unsubscribe: ':no_entry_sign:', wrong_person: ':arrows_counterclockwise:', out_of_office: ':palm_tree:', auto_reply: ':robot_face:', unclear: ':question:' }[intent] || ':envelope:';

const lines = [
  icon + ' *' + intent.toUpperCase().split('_').join(' ') + '* - ' + (source.first_name || source.email) + ' at ' + (source.company || source.domain),
  source.summary
];

if (source.referred_to_someone) lines.push('Referred to: ' + source.referred_to_someone);
if (source.follow_up_on) lines.push('Follow up on: ' + source.follow_up_on);
if (intent === 'interested') lines.push('GHL contact created, booking link sent.');
if (source.suggested_reply) lines.push('\nDraft reply:\n> ' + source.suggested_reply.split('\n').join('\n> '));

return [{ json: { text: lines.join('\n'), intent: intent } }];
